:root{--font-display:'Inter',system-ui,sans-serif;--font-body:'Instrument Sans','Inter',system-ui,sans-serif;--font-mono:'JetBrains Mono',ui-monospace,monospace;--maxw:1200px;--r:14px;--shadow:0 24px 60px -28px rgba(0,0,0,.85);--ease:cubic-bezier(.22,.7,.28,1);--bg:#100E09;--bg2:#1A160E;--line:#3B3122;--accent:#D9B44A;--accent-hi:#F5E3A6;--accent-lo:#87681E;--paper:#F9F2DD;--paper2:#F1E5C4;--ink:#221C10;--muted:#9C8F71;--on-dark:#F0E4C3}
body[data-palette="gilt"]{--bg:#100E09;--bg2:#1A160E;--line:#3B3122;--accent:#D9B44A;--accent-hi:#F5E3A6;--accent-lo:#87681E;--paper:#F9F2DD;--paper2:#F1E5C4;--ink:#221C10;--muted:#9C8F71;--on-dark:#F0E4C3}
body[data-palette="woodland"]{--bg:#283618;--bg2:#34451f;--line:#606C38;--accent:#DDA15E;--accent-hi:#FEFAE0;--accent-lo:#BC6C25;--paper:#FEFAE0;--paper2:#f5eccf;--ink:#283618;--muted:#b9c69c;--on-dark:#FEFAE0}
body[data-palette="tranquil"]{--bg:#1F363D;--bg2:#294750;--line:#40798C;--accent:#70A9A1;--accent-hi:#CFE0C3;--accent-lo:#40798C;--paper:#eef6ee;--paper2:#CFE0C3;--ink:#1F363D;--muted:#a8c2c2;--on-dark:#eef6ee}
*{box-sizing:border-box}body.aurum-body{margin:0;background:var(--bg);color:var(--on-dark);font-family:var(--font-body);line-height:1.65}.aurum-wrap{max-width:var(--maxw);margin-inline:auto;padding-inline:clamp(18px,4vw,34px)}.aurum-nav{position:sticky;top:0;z-index:900;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(16px);border-bottom:1px solid var(--line);overflow:visible}.aurum-nav::after{content:'';position:absolute;inset:auto 0 -1px;height:1px;background:linear-gradient(90deg,transparent,var(--accent-lo),var(--accent),var(--accent-lo),transparent)}.aurum-nav-in{height:70px;display:flex;align-items:center;gap:20px}.aurum-brand{display:flex;flex-direction:column;color:var(--accent-hi)!important;min-width:max-content}.aurum-brand b{font-weight:900;letter-spacing:.08em}.aurum-brand span{font:600 .55rem/1.2 var(--font-mono);letter-spacing:.2em;color:var(--muted)}.aurum-brand i{height:2px;margin-top:4px;background:linear-gradient(90deg,var(--accent-lo),var(--accent-hi),var(--accent-lo))}.aurum-menu{display:flex;gap:4px;flex:1}.aurum-link{padding:9px 12px;border-radius:8px;color:var(--on-dark)!important;font-weight:700}.aurum-link:hover,.aurum-link.active{background:var(--bg2);color:var(--accent-hi)!important}.aurum-actions{display:flex;align-items:center;gap:8px}.aurum-dd{position:relative}.aurum-dd summary,.aurum-signout,.aurum-signin{list-style:none;padding:8px 12px;border:1px solid var(--line);border-radius:9px;background:var(--bg2);color:var(--accent-hi);font-weight:700;cursor:pointer}.aurum-panel{position:absolute;right:0;top:calc(100% + 9px);min-width:220px;padding:8px;background:var(--paper)!important;border:1px solid color-mix(in srgb,var(--accent) 40%,#000);border-radius:12px;box-shadow:var(--shadow);display:grid;z-index:1500}.aurum-panel a{padding:9px 10px;border-radius:7px;color:var(--ink)!important;font-weight:700}.aurum-panel a:hover{background:var(--paper2)!important;color:var(--accent-lo)!important}.aurum-main{min-height:70vh}.aurum-context{background:var(--bg2);border-bottom:1px solid var(--line)}.aurum-context .aurum-wrap{padding-block:14px}.aurum-context .page-kicker{font:600 .65rem var(--font-mono);letter-spacing:.15em;text-transform:uppercase;color:var(--accent)}.aurum-context .page-title{font-weight:850;color:var(--accent-hi)}.aurum-page>.section-head,.aurum-page>.admin-shell,.aurum-page>.card,.aurum-page>.container,.aurum-page>.section{max-width:var(--maxw);margin-inline:auto}.aurum-page{min-height:60vh}.aurum-page:not(:has(.aurum-hero)){padding:28px clamp(18px,4vw,34px)}.aurum-hero{position:relative;overflow:hidden;border-bottom:1px solid var(--line);background:radial-gradient(70% 90% at 72% 45%,color-mix(in srgb,var(--accent) 24%,transparent),transparent 70%)}.aurum-hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:center;padding:70px 34px 85px}.aurum-eyebrow{font:600 .7rem var(--font-mono);letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}.aurum-eyebrow.dark{color:var(--accent-lo)}.aurum-hero h1{font:900 clamp(2.6rem,5vw,4.3rem)/1.06 var(--font-display);color:var(--on-dark);margin:18px 0}.aurum-hero h1 em{font-style:normal;color:var(--accent-hi)}.aurum-lede{max-width:48ch;color:var(--muted);font-size:1.06rem}.aurum-cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.aurum-btn{display:inline-flex;padding:11px 20px;border-radius:999px;font-weight:800}.aurum-btn-gold{background:linear-gradient(150deg,var(--accent-hi),var(--accent) 48%,var(--accent-lo));color:#171205!important}.aurum-btn-ghost{border:1px solid var(--accent-lo);color:var(--accent-hi)!important}.aurum-meta{display:flex;gap:24px;flex-wrap:wrap;margin-top:34px;padding-top:22px;border-top:1px solid var(--line)}.aurum-meta b{display:block;color:var(--accent-hi);font:700 1rem var(--font-mono)}.aurum-meta span{color:var(--muted);font-size:.75rem}.aurum-seal{aspect-ratio:1;border-radius:24px;border:1px solid transparent;background:radial-gradient(100% 100% at 30% 15%,var(--bg2),var(--bg)) padding-box,linear-gradient(150deg,var(--accent-lo),var(--accent-hi),var(--accent),var(--accent-lo)) border-box;display:grid;place-items:center;box-shadow:var(--shadow)}.aurum-seal-ring{width:65%;aspect-ratio:1;border-radius:50%;border:8px double var(--accent);display:grid;place-items:center;align-content:center;box-shadow:inset 0 0 0 2px var(--accent-hi)}.aurum-seal-ring span{font:900 clamp(3rem,7vw,6rem) var(--font-display);color:var(--accent-hi)}.aurum-seal-ring small{font:600 .65rem var(--font-mono);letter-spacing:.25em;color:var(--accent)}.aurum-section{padding-block:60px}.aurum-paper{background:var(--paper);color:var(--ink);border-radius:20px;padding:clamp(24px,4vw,44px);border:1px solid var(--accent-lo);box-shadow:var(--shadow)}.aurum-section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:10px 0 28px}.aurum-section-head h2{color:var(--ink)}.aurum-section-head a{color:var(--accent-lo)!important;font-weight:800}.aurum-page .card,.aurum-page .table-wrap,.aurum-page .panel-tabs,.aurum-page .admin-nav{border-color:color-mix(in srgb,var(--accent-lo) 35%,#bbb)}.aurum-page .btn-primary{background:var(--accent)!important;border-color:var(--accent)!important;color:#171205!important}.aurum-footer{border-top:1px solid var(--line);background:var(--bg2);padding:35px 0;color:var(--muted)}.aurum-footer .aurum-wrap{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap}.aurum-footer strong,.aurum-footer a{color:var(--accent-hi)!important}.aurum-footer p{max-width:50ch;margin:.4rem 0 0}@media(max-width:900px){.aurum-hero-grid{grid-template-columns:1fr}.aurum-seal{max-width:460px}.aurum-menu{display:none}.aurum-nav-in{gap:8px}.aurum-actions{margin-left:auto;flex-wrap:wrap}.aurum-context{margin-top:0}}
